for step in range(MAX_AGENT_STEPS):
  response = call_llm(messages, tools)
  assistant = response.choices[0].message
  messages.append(assistant)
  if not assistant.tool_calls:
    return assistant.content
  for call in assistant.tool_calls:
    args = parse_and_validate(call.function.arguments)
    result = execute_allowed_tool(call.function.name, args)
    messages.append({role: "tool", tool_call_id: call.id, content: serialize(result)})
return {status: "step_limit_reached"}
